#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <stdbool.h>

typedef struct TreeNode {
    int val;
    struct TreeNode* left;
    struct TreeNode* right;
} TreeNode;

typedef struct {
    const char* s;
    size_t pos;
    size_t len;
} Parser;

static void skip_ws(Parser* p) {
    while (p->pos < p->len && isspace((unsigned char)p->s[p->pos])) p->pos++;
}

static void expect_char(Parser* p, char c) {
    skip_ws(p);
    if (p->pos >= p->len || p->s[p->pos] != c) {
        fprintf(stderr, "Invalid input\n");
        exit(1);
    }
    p->pos++;
}

static bool read_nullable_int(Parser* p, int* out) {
    skip_ws(p);
    if (p->pos + 4 <= p->len && strncmp(p->s + p->pos, "null", 4) == 0) {
        p->pos += 4;
        return false;
    }

    int sign = 1;
    if (p->pos < p->len && p->s[p->pos] == '-') {
        sign = -1;
        p->pos++;
    }

    if (p->pos >= p->len || !isdigit((unsigned char)p->s[p->pos])) {
        fprintf(stderr, "Invalid integer\n");
        exit(1);
    }

    int value = 0;
    while (p->pos < p->len && isdigit((unsigned char)p->s[p->pos])) {
        value = value * 10 + (p->s[p->pos] - '0');
        p->pos++;
    }
    *out = sign * value;
    return true;
}

typedef struct {
    bool present;
    int value;
} OptInt;

static OptInt* read_tree_list(Parser* p, size_t* count) {
    expect_char(p, '[');
    size_t cap = 16, n = 0;
    OptInt* values = (OptInt*)malloc(cap * sizeof(OptInt));

    skip_ws(p);
    if (p->pos < p->len && p->s[p->pos] == ']') {
        p->pos++;
        *count = 0;
        return values;
    }

    while (1) {
        if (n == cap) {
            cap *= 2;
            values = (OptInt*)realloc(values, cap * sizeof(OptInt));
        }
        int x = 0;
        values[n].present = read_nullable_int(p, &x);
        values[n].value = x;
        n++;

        skip_ws(p);
        if (p->pos < p->len && p->s[p->pos] == ',') {
            p->pos++;
            continue;
        }
        expect_char(p, ']');
        *count = n;
        return values;
    }
}

static TreeNode* new_node(int value) {
    TreeNode* n = (TreeNode*)malloc(sizeof(TreeNode));
    n->val = value;
    n->left = NULL;
    n->right = NULL;
    return n;
}

static TreeNode* from_list(const OptInt* values, size_t count) {
    if (count == 0 || !values[0].present) return NULL;

    TreeNode* root = new_node(values[0].value);
    size_t cap = count * 2 + 4;
    TreeNode** queue = (TreeNode**)malloc(cap * sizeof(TreeNode*));
    size_t head = 0, tail = 0, i = 1;
    queue[tail++] = root;

    while (head < tail && i < count) {
        TreeNode* cur = queue[head++];

        if (i < count) {
            if (values[i].present) {
                cur->left = new_node(values[i].value);
                queue[tail++] = cur->left;
            }
            i++;
        }

        if (i < count) {
            if (values[i].present) {
                cur->right = new_node(values[i].value);
                queue[tail++] = cur->right;
            }
            i++;
        }
    }

    free(queue);
    return root;
}

TreeNode* addOneRow(TreeNode* root, int val, int depth) {
    if (depth == 1) {
        TreeNode* node = new_node(val);
        node->left = root;
        return node;
    }
    if (root == NULL) return NULL;

    TreeNode** level = (TreeNode**)malloc(2 * sizeof(TreeNode*));
    size_t count = 1, cap = 2;
    level[0] = root;

    for (int d = 1; d < depth - 1; d++) {
        TreeNode** next = (TreeNode**)malloc((count * 2 + 1) * sizeof(TreeNode*));
        size_t next_count = 0;
        for (size_t i = 0; i < count; i++) {
            if (level[i]->left) next[next_count++] = level[i]->left;
            if (level[i]->right) next[next_count++] = level[i]->right;
        }
        free(level);
        level = next;
        count = next_count;
        cap = count + 1;
    }

    for (size_t i = 0; i < count; i++) {
        TreeNode* cur = level[i];
        TreeNode* old_left = cur->left;
        TreeNode* old_right = cur->right;

        cur->left = new_node(val);
        cur->left->left = old_left;

        cur->right = new_node(val);
        cur->right->right = old_right;
    }

    free(level);
    (void)cap;
    return root;
}

static void print_json(TreeNode* root) {
    if (!root) {
        printf("[]\n");
        return;
    }

    size_t cap = 16, n = 0, head = 0;
    TreeNode** queue = (TreeNode**)malloc(cap * sizeof(TreeNode*));
    queue[n++] = root;

    while (head < n) {
        TreeNode* cur = queue[head++];
        if (cur) {
