    vector<TreeNode*> q{root};
    size_t head = 0;
    while (head < q.size()) {
        TreeNode* cur = q[head++];
        if (cur) {
            q.push_back(cur->left);
            q.push_back(cur->right);
        }
    }

    size_t last = q.size();
    while (last > 0 && q[last - 1] == nullptr) --last;

    ostringstream out;
    out << '[';
